    public static void MergeInto(Configuration configuration)
    {
        configuration.Fights.RemoveAll(fight => fight.IsBuiltIn && (fight.Id == "m12s-p1" || fight.Id == "m12s-p2"));
        foreach (var preset in CreateAll())
        {
            var existing = configuration.Fights.FirstOrDefault(fight => fight.Id == preset.Id);
            if (existing is null)
                configuration.Fights.Add(preset);
            else
            {
                existing.Category = preset.Category;
                existing.ContentFinderConditionId = preset.ContentFinderConditionId;
                existing.IsBuiltIn = true;
                existing.SourceUrl = preset.SourceUrl;
                existing.PresetStatus = preset.PresetStatus;
                existing.Phases = preset.Phases;
                existing.SyncTriggers = preset.SyncTriggers;
                existing.StateTransitions = preset.StateTransitions;
                if (existing.Timeline.Count == 0)
                    existing.Timeline = preset.Timeline;
            }
        }
    }

    private static TimelineItem Item(int seconds, string skill, string note, string job, string role) => new()
    {
        TimeSeconds = seconds, Skill = skill, Note = note, TargetJob = job, TargetRole = role
    };
